BLOODELF_INFO = "Blood Elf\n\n|cffe6e600Survivors of a brutal war, the blood\n elves drew their strength from the magic\n of the Sunwell to rebuild their kingdom.|r\n\n";
DRACTHYR_A_INFO = "Blood Elf\n\n|cffe6e600Created by Neltharion the Earth-Warder, the essence of dragons was combined with the adaptability of mortal races to create an elite armed force able to shift between draconic and humanoid form.|r\n\n";
