DRACTHYR_H_INFO = "Human\n\n|cffe6e600Created by Neltharion the Earth-Warder, the essence of dragons was combined with the adaptability of mortal races to create an elite armed force able to shift between draconic and humanoid form.\n\n";
WORGEN_INFO = "Worgen\n\n|cffe6e600The noble humans of Stormwind stand\n at the vanguard of the Alliance against\n the enemies of Azeroth.\n\n";
NIGHTELF_INFO = "Night Elf\n\n|cffe6e600The mystical night elves defend\n the wilds of Azeroth against all who would\n cause harm to nature.\n\n";
